using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace ApiMcpServer.Tools;

/// <summary>
/// MCP tools that wrap a REST API using HttpClient.
/// Uses constructor injection — the SDK resolves DI services automatically
/// and they do NOT appear in the tool's JSON schema.
/// </summary>
[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    [McpServerTool, Description("List all users from the API.")]
    public async Task<string> ListUsers(
        [Description("Maximum number of results to return (1-100)")] int limit = 10,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Listing up to {Limit} users", limit);
        var response = await httpClient.GetFromJsonAsync<List<User>>(
            $"/users?_limit={limit}", cancellationToken);

        if (response is null || response.Count == 0)
            return "No users found.";

        return string.Join("\n", response.Select(u => $"- {u.Name} ({u.Email})"));
    }

    [McpServerTool, Description("Get a single user by their numeric ID.")]
    public async Task<string> GetUser(
        [Description("The user's numeric ID")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching user {UserId}", userId);
        var response = await httpClient.GetAsync($"/users/{userId}", cancellationToken);

        if (!response.IsSuccessStatusCode)
            return $"Error: API returned {(int)response.StatusCode} {response.ReasonPhrase}";

        var user = await response.Content.ReadFromJsonAsync<User>(cancellationToken);
        return user is null
            ? "User not found."
            : $"Name: {user.Name}\nEmail: {user.Email}\nPhone: {user.Phone}\nCompany: {user.Company?.Name}";
    }

    [McpServerTool, Description("Search for posts by a specific user.")]
    public async Task<string> GetUserPosts(
        [Description("The user's numeric ID to get posts for")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching posts for user {UserId}", userId);
        var posts = await httpClient.GetFromJsonAsync<List<Post>>(
            $"/posts?userId={userId}", cancellationToken);

        if (posts is null || posts.Count == 0)
            return "No posts found for this user.";

        return string.Join("\n\n", posts.Select(p => $"## {p.Title}\n{p.Body}"));
    }
}

// DTOs for the JSONPlaceholder API
public record User(
    int Id,
    string Name,
    string Email,
    string? Phone,
    Company? Company);

public record Company(string Name);

public record Post(
    int Id,
    int UserId,
    string Title,
    string Body);

